package com.asmj.marketplace.shopadvertising;

import com.asmj.marketplace.advertising.AdvertisingSettings;
import com.asmj.marketplace.advertising.AdvertisingSettingsRepository;
import com.asmj.marketplace.audit.AuditService;
import com.asmj.marketplace.model.*;
import com.asmj.marketplace.notification.NotificationService;
import com.asmj.marketplace.product.*;
import com.asmj.marketplace.repository.*;
import com.asmj.marketplace.service.CloudinaryImageService;
import java.math.BigDecimal;
import java.security.Principal;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class ShopAdvertisingController {
 private final ShopAdvertisementRepository ads; private final ShopAdCategoryRepository shopCategories; private final UserAccountRepository users; private final VendorProfileRepository profiles; private final ProductRepository products; private final AdvertisingSettingsRepository adSettings; private final CloudinaryImageService uploads; private final AuditService audit; private final NotificationService notifications;
 @Value("${app.shop-advertising.price:499}") private BigDecimal price;
 @Value("${app.shop-advertising.duration-days:30}") private int durationDays;
 public ShopAdvertisingController(ShopAdvertisementRepository a,ShopAdCategoryRepository sc,UserAccountRepository u,VendorProfileRepository vp,ProductRepository p,AdvertisingSettingsRepository as,CloudinaryImageService up,AuditService au,NotificationService ns){ads=a;shopCategories=sc;users=u;profiles=vp;products=p;adSettings=as;uploads=up;audit=au;notifications=ns;}

 @GetMapping("/shops") public String directory(@RequestParam(required=false) String q,@RequestParam(required=false) String category,Model m){List<ShopAdvertisement> live=ads.findAll().stream().filter(this::isLiveAndVendorApproved).filter(a->q==null||q.isBlank()||(a.getShopName()!=null&&a.getShopName().toLowerCase(Locale.ROOT).contains(q.trim().toLowerCase(Locale.ROOT)))).filter(a->category==null||category.isBlank()||category.equals(a.getCategoryId())).sorted(Comparator.comparing(ShopAdvertisement::getCreatedAt).reversed()).toList();m.addAttribute("shops",live);m.addAttribute("categories",shopCategories.findByActiveTrueOrderByNameAsc());m.addAttribute("q",q);m.addAttribute("selectedCategory",category);return "shops/directory";}
 @GetMapping("/shops/{id}") public String storefront(@PathVariable String id,Model m){ShopAdvertisement ad=ads.findById(id).filter(this::isLiveAndVendorApproved).orElse(null);if(ad==null)return "redirect:/shops";ad.setClicks(ad.getClicks()+1);ads.save(ad);List<Product> available=products.findByVendorUserIdOrderByCreatedAtDesc(ad.getVendorUserId()).stream().filter(p->p.getStatus()==ProductStatus.ACTIVE).filter(p->p.getStockQuantity()==null||p.getStockQuantity()>0).toList();m.addAttribute("shopAd",ad);m.addAttribute("products",available);m.addAttribute("profile",profiles.findByUserId(ad.getVendorUserId()).orElse(null));return "shops/storefront";}
 @GetMapping("/shops/impression/{id}") @ResponseBody public String impression(@PathVariable String id){ads.findById(id).filter(this::isLiveAndVendorApproved).ifPresent(a->{a.setImpressions(a.getImpressions()+1);ads.save(a);});return "ok";}

 @GetMapping("/vendor/shop-advertising") public String vendorAds(Principal p,Model m){UserAccount u=current(p);m.addAttribute("ads",ads.findByVendorUserIdOrderByCreatedAtDesc(u.getId()));m.addAttribute("categories",shopCategories.findByActiveTrueOrderByNameAsc());m.addAttribute("price",price);m.addAttribute("durationDays",durationDays);m.addAttribute("settings",currentSettings());return "shops/vendor-advertising";}
 @PostMapping("/vendor/shop-advertising/create") public String create(Principal p,@RequestParam String shopName,@RequestParam String categoryId,@RequestParam(required=false) String description,@RequestParam String startDate,@RequestParam String paymentUtr,@RequestParam MultipartFile banner,@RequestParam(required=false) MultipartFile logo,@RequestParam MultipartFile paymentProof,@RequestParam(required=false) String regulatoryLicenceNumber,@RequestParam(required=false) MultipartFile regulatoryLicenceProof,RedirectAttributes ra){try{UserAccount u=current(p);if(u.getRole()!=Role.ROLE_VENDOR||u.getVendorStatus()!=VendorStatus.APPROVED)throw new IllegalArgumentException("Only approved vendors can advertise a shop.");AdvertisingSettings paySettings=currentSettings();if(!paySettings.isEnabled()||paySettings.getUpiId()==null||paySettings.getUpiId().isBlank())throw new IllegalArgumentException("Shop advertising is unavailable until Admin configures the advertising UPI details.");if(price==null||price.signum()<=0||durationDays<1||durationDays>365)throw new IllegalArgumentException("Shop advertising package is not configured correctly. Contact Admin.");if(shopName.trim().length()<3||shopName.trim().length()>100)throw new IllegalArgumentException("Shop name must be 3–100 characters.");if(description!=null&&description.length()>500)throw new IllegalArgumentException("Description is limited to 500 characters.");ShopAdCategory cat=shopCategories.findById(categoryId).filter(ShopAdCategory::isActive).orElseThrow(()->new IllegalArgumentException("Choose an active shop category."));LocalDate start=LocalDate.parse(startDate);LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));if(start.isBefore(today)||start.isAfter(today.plusDays(60)))throw new IllegalArgumentException("Choose a start date within the next 60 days.");if(paymentUtr==null||!paymentUtr.trim().matches("[A-Za-z0-9]{8,30}")||ads.existsByPaymentUtrIgnoreCaseAndIdNot(paymentUtr.trim(),""))throw new IllegalArgumentException("Enter a valid unique UPI UTR/reference (8–30 characters).");if(banner==null||banner.isEmpty()||paymentProof==null||paymentProof.isEmpty())throw new IllegalArgumentException("Upload the shop banner and UPI payment screenshot.");boolean pharmacy=cat.getName().toLowerCase(Locale.ROOT).contains("pharma");if(pharmacy&&(regulatoryLicenceNumber==null||regulatoryLicenceNumber.trim().isEmpty()||regulatoryLicenceProof==null||regulatoryLicenceProof.isEmpty()))throw new IllegalArgumentException("Pharmaceutical shops must provide a valid pharmacy licence number and licence document for Admin review.");String bannerUrl=(String)uploads.uploadAdvertisementBanner(banner).get("secure_url");String logoUrl=logo!=null&&!logo.isEmpty()?(String)uploads.uploadProfilePhoto(logo).get("secure_url"):null;String proof=(String)uploads.uploadDocument(paymentProof,"asmj-marketplace/shop-advertising/payments").get("secure_url");ShopAdvertisement ad=new ShopAdvertisement();ad.setVendorUserId(u.getId());ad.setVendorName(u.getFullName());ad.setShopName(shopName.trim());ad.setCategoryId(cat.getId());ad.setCategoryName(cat.getName());ad.setDescription(description==null?"":description.trim());ad.setRegulatoryLicenceNumber(regulatoryLicenceNumber==null?null:regulatoryLicenceNumber.trim());if(regulatoryLicenceProof!=null&&!regulatoryLicenceProof.isEmpty())ad.setRegulatoryLicenceProofUrl((String)uploads.uploadDocument(regulatoryLicenceProof,"asmj-marketplace/shop-advertising/licences").get("secure_url"));ad.setBannerUrl(bannerUrl);ad.setLogoUrl(logoUrl);ad.setAmount(price);ad.setDurationDays(durationDays);ad.setStartDate(start);ad.setEndDate(start.plusDays(durationDays-1L));ad.setPaymentUtr(paymentUtr.trim());ad.setPaymentProofUrl(proof);ad.setPaymentStatus("PENDING");ad.setApprovalStatus("PENDING");ad.setStatus("PENDING_PAYMENT");ads.save(ad);notifications.notifyAdmins("New shop advertisement submitted","A paid shop advertisement for "+ad.getShopName()+" is awaiting payment verification.","SHOP_ADVERTISEMENT",ad.getId());audit.record(u.getEmail(),"VENDOR","SHOP_AD_SUBMITTED","SHOP_ADVERTISEMENT",ad.getId(),"Shop advertisement submitted for payment verification and approval.");ra.addFlashAttribute("successMessage","Shop advertisement submitted. It will appear only after Admin verifies payment and approves it.");}catch(Exception e){ra.addFlashAttribute("errorMessage",msg(e));}return "redirect:/vendor/shop-advertising";}

 @GetMapping("/admin/shop-advertising") public String adminAds(Model m){m.addAttribute("ads",ads.findAllByOrderByCreatedAtDesc());m.addAttribute("categories",shopCategories.findAll());return "shops/admin-advertising";}
 @PostMapping("/admin/shop-advertising/{id}/verify") public String verify(@PathVariable String id,Principal p,RedirectAttributes ra){try{ShopAdvertisement a=ads.findById(id).orElseThrow(()->new IllegalArgumentException("Shop advertisement not found."));if(!"PENDING".equals(a.getPaymentStatus()))throw new IllegalArgumentException("Payment is not awaiting verification.");a.setPaymentStatus("VERIFIED");a.setVerifiedBy(current(p).getEmail());a.setVerifiedAt(Instant.now());a.setStatus("PENDING_APPROVAL");a.setUpdatedAt(Instant.now());ads.save(a);notifications.notifyUser(a.getVendorUserId(),"Shop advertisement payment verified","Payment for "+a.getShopName()+" was verified. The advertisement is awaiting approval.","SHOP_ADVERTISEMENT",id);audit.record(current(p).getEmail(),"ADMIN","SHOP_AD_PAYMENT_VERIFIED","SHOP_ADVERTISEMENT",id,"UPI payment verified.");ra.addFlashAttribute("successMessage","Payment verified. Approve the advertisement separately.");}catch(Exception e){ra.addFlashAttribute("errorMessage",msg(e));}return "redirect:/admin/shop-advertising";}
 @PostMapping("/admin/shop-advertising/{id}/approve") public String approve(@PathVariable String id,Principal p,RedirectAttributes ra){try{ShopAdvertisement a=ads.findById(id).orElseThrow(()->new IllegalArgumentException("Shop advertisement not found."));if(!"VERIFIED".equals(a.getPaymentStatus()))throw new IllegalArgumentException("Verify payment before approval.");if(a.getStartDate()==null||a.getEndDate()==null||a.getEndDate().isBefore(LocalDate.now(ZoneId.of("Asia/Kolkata"))))throw new IllegalArgumentException("Advertising dates have expired. Ask vendor to submit a new request.");a.setApprovalStatus("APPROVED");a.setApprovedBy(current(p).getEmail());a.setApprovedAt(Instant.now());a.setStatus("APPROVED");a.setUpdatedAt(Instant.now());ads.save(a);notifications.notifyUser(a.getVendorUserId(),"Shop advertisement approved",a.getShopName()+" is approved and will appear in the Shops directory during its scheduled dates.","SHOP_ADVERTISEMENT",id);audit.record(current(p).getEmail(),"ADMIN","SHOP_AD_APPROVED","SHOP_ADVERTISEMENT",id,"Paid shop advertisement approved.");ra.addFlashAttribute("successMessage","Shop advertisement approved.");}catch(Exception e){ra.addFlashAttribute("errorMessage",msg(e));}return "redirect:/admin/shop-advertising";}
 @PostMapping("/admin/shop-advertising/{id}/reject") public String reject(@PathVariable String id,@RequestParam String reason,Principal p,RedirectAttributes ra){try{ShopAdvertisement a=ads.findById(id).orElseThrow(()->new IllegalArgumentException("Shop advertisement not found."));if(reason==null||reason.trim().length()<4||reason.length()>500)throw new IllegalArgumentException("Enter a rejection reason (4–500 characters).");a.setApprovalStatus("REJECTED");a.setStatus("REJECTED");a.setRejectionReason(reason.trim());a.setUpdatedAt(Instant.now());ads.save(a);notifications.notifyUser(a.getVendorUserId(),"Shop advertisement rejected",a.getShopName()+" was not approved: "+reason,"SHOP_ADVERTISEMENT",id);ra.addFlashAttribute("successMessage","Advertisement rejected and vendor notified.");}catch(Exception e){ra.addFlashAttribute("errorMessage",msg(e));}return "redirect:/admin/shop-advertising";}
 @PostMapping("/admin/shop-advertising/{id}/suspend") public String suspend(@PathVariable String id,Principal p,RedirectAttributes ra){ShopAdvertisement a=ads.findById(id).orElse(null);if(a==null){ra.addFlashAttribute("errorMessage","Shop advertisement not found.");return "redirect:/admin/shop-advertising";}a.setStatus("SUSPENDED");a.setUpdatedAt(Instant.now());ads.save(a);notifications.notifyUser(a.getVendorUserId(),"Shop advertisement suspended",a.getShopName()+" has been suspended by ASMJ Shoppe Admin.","SHOP_ADVERTISEMENT",id);audit.record(current(p).getEmail(),"ADMIN","SHOP_AD_SUSPENDED","SHOP_ADVERTISEMENT",id,"Shop advertisement suspended.");ra.addFlashAttribute("successMessage","Shop advertisement suspended.");return "redirect:/admin/shop-advertising";}
 @PostMapping("/admin/shop-advertising/category") public String addCategory(@RequestParam String name,RedirectAttributes ra){try{String n=name==null?"":name.trim();if(n.length()<3||n.length()>60)throw new IllegalArgumentException("Category name must be 3–60 characters.");if(shopCategories.findByNameIgnoreCase(n).isPresent())throw new IllegalArgumentException("That shop category already exists.");ShopAdCategory c=new ShopAdCategory();c.setName(n);shopCategories.save(c);ra.addFlashAttribute("successMessage","Shop category added.");}catch(Exception e){ra.addFlashAttribute("errorMessage",msg(e));}return "redirect:/admin/shop-advertising";}
 @PostMapping("/admin/shop-advertising/category/{id}/toggle") public String toggleCategory(@PathVariable String id,RedirectAttributes ra){shopCategories.findById(id).ifPresent(c->{c.setActive(!c.isActive());shopCategories.save(c);});ra.addFlashAttribute("successMessage","Shop category updated.");return "redirect:/admin/shop-advertising";}
 private boolean isLiveAndVendorApproved(ShopAdvertisement a){if(!a.isLive()||a.getVendorUserId()==null||a.getVendorUserId().isBlank())return false;ShopAdCategory category=shopCategories.findById(a.getCategoryId()).orElse(null);if(category==null||!category.isActive())return false;UserAccount v=users.findById(a.getVendorUserId()).orElse(null);return v!=null&&v.isEnabled()&&v.getRole()==Role.ROLE_VENDOR&&v.getVendorStatus()==VendorStatus.APPROVED;} private AdvertisingSettings currentSettings(){return adSettings.findById("default").orElseGet(AdvertisingSettings::new);} private UserAccount current(Principal p){return users.findByEmailIgnoreCase(p.getName()).orElseThrow();} private String msg(Exception e){return e.getMessage()==null?"Unable to process shop advertisement.":e.getMessage();}
}
